<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Review Moderation | NexalyPlanner</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#2c2117;font-family:Inter,system-ui,sans-serif}.wrap{max-width:1080px;margin:auto;padding:42px 20px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}h1{font-family:Georgia,serif;margin:0}.card{background:#fff;border:1px solid #e4dac8;border-radius:16px;padding:22px;box-shadow:0 10px 30px #49351a10}.login{max-width:440px;margin:12vh auto}.login input{width:100%;margin:12px 0;padding:13px;border:1px solid #cdbfa8;border-radius:10px}.btn{border:0;border-radius:9px;padding:11px 15px;font-weight:750;cursor:pointer;background:#2c2117;color:#fff}.btn.approve{background:#23633f}.btn.reject{background:#8b3232}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.filters button{background:#fff;color:#514432;border:1px solid #d9cdbb}.filters button.on{background:#2c2117;color:#fff}.item{margin:12px 0}.meta{display:flex;gap:9px;flex-wrap:wrap;color:#786b59;font-size:13px}.tag{border-radius:99px;background:#eee6da;padding:3px 8px}.stars{color:#bd6b2f;letter-spacing:2px}.message{white-space:pre-wrap;line-height:1.55}.actions{display:flex;gap:9px;margin-top:16px}.empty{text-align:center;padding:45px;color:#786b59}@media(max-width:600px){.top{align-items:flex-start;gap:12px;flex-direction:column}.card{padding:16px}}</style></head><body><main class="wrap"><section class="card login" id="login"><h1>Review moderation</h1><p>Approve public reviews and keep suggestions or issue reports private.</p><form id="loginForm"><input type="password" id="password" autocomplete="current-password" placeholder="Admin password" required><button class="btn">Sign in securely</button><p id="loginMsg"></p></form></section><section id="panel" hidden><div class="top"><div><h1>Customer feedback</h1><p>Only approved reviews with customer consent appear publicly.</p></div><button class="btn" id="logout">Sign out</button></div><div class="filters" id="filters"></div><div id="list"></div></section></main>
<script>let csrf='',records=[],filter='pending';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(url,opt){const r=await fetch(url,opt),j=await r.json();if(!r.ok)throw Error(j.message||'Request failed');return j}async function load(){const j=await api('api.php?action=list&product=all');csrf=j.csrf;records=j.records;document.querySelector('#login').hidden=true;document.querySelector('#panel').hidden=false;render()}function render(){const counts={all:records.length,pending:0,approved:0,rejected:0,review:0,suggestion:0,issue:0,comment:0};records.forEach(r=>{counts[r.status]=(counts[r.status]||0)+1;counts[r.type]=(counts[r.type]||0)+1});const fs=['pending','review','suggestion','issue','comment','approved','rejected','all'];document.querySelector('#filters').innerHTML=fs.map(f=>`<button class="btn ${filter===f?'on':''}" onclick="filter='${f}';render()">${f[0].toUpperCase()+f.slice(1)} (${counts[f]||0})</button>`).join('');const rows=records.filter(r=>filter==='all'||r.status===filter||r.type===filter);document.querySelector('#list').innerHTML=rows.length?rows.map(r=>`<article class="card item"><div class="meta"><span class="tag">${esc(r.product)}</span><span class="tag">${esc(r.type)}</span><span class="tag">${esc(r.status)}</span>${r.rating?`<span class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span>`:''}<span>${new Date(r.created_at).toLocaleString()}</span><span>${r.publish_consent?'Public consent given':'Private only'}</span></div><h3>${esc(r.title||r.name||'Customer submission')}</h3>${r.email?`<p><strong>Reply email:</strong> ${esc(r.email)}</p>`:''}<p class="message">${esc(r.message)}</p>${r.status==='pending'?`<div class="actions">${r.type==='review'&&r.publish_consent?`<button class="btn approve" onclick="moderate('${r.id}','${r.product}','approved')">Approve review</button>`:''}<button class="btn reject" onclick="moderate('${r.id}','${r.product}','rejected')">Reject / archive</button></div>`:''}</article>`).join(''):'<div class="card empty">No submissions in this category.</div>'}async function moderate(id,product,status){await api('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'moderate',product,id,status,csrf})});await load()}document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();try{const j=await api('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',password:document.querySelector('#password').value})});csrf=j.csrf;await load()}catch(x){document.querySelector('#loginMsg').textContent=x.message}};document.querySelector('#logout').onclick=async()=>{await api('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});location.reload()};load().catch(()=>{});</script></body></html>
